contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        c.fallback{value: depositAmount}();

        uint256 balBefore = c.balances(address(this));
        require(balBefore == depositAmount);

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balances(address(this));

        if (reverted) {
            assert(balAfter == balBefore);
        } else {
            assert(balAfter == 0);
        }
    }

    receive() external payable {}
}

