contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Setup: give c some Ether and record the balance attributed to this test contract.
        c.fallback{value: amount}();
        uint256 beforeBal = c.balances(address(this));

        // Deciding call: withdraw exactly the attributed balance.
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        // General rule: after any completed withdraw(), the caller's balance entry must be zero.
        assert(reverted || c.balances(address(this)) == 0);
    }

    receive() external payable {}

    fallback() external payable {}
}

