contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 prepay, uint256 extra) public payable {
        // Prepay the test contract's balance in c by sending Ether to its fallback.
        require(address(this).balance >= prepay);
        (bool prepaid, ) = address(c).call{value: prepay}("");
        require(prepaid);

        uint256 balanceBefore = c.balances(address(this));
        uint256 contractBefore = address(c).balance;
        require(balanceBefore == prepay);

        uint256 amount = balanceBefore;

        // One extra wei sent as value so that a successful call also observes
        // that c's payable fallback is reachable and can accept value.
        uint256 valueSent = extra == 0 ? 0 : 1;
        require(address(this).balance >= valueSent);

        bool reverted;
        try c.withdraw{value: valueSent}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balances(address(this));
        uint256 contractAfter = address(c).balance;

        if (!reverted) {
            assert(balanceAfter == 0);
            assert(contractBefore >= amount);
            assert(contractAfter <= contractBefore - amount + valueSent);
        } else {
            assert(balanceAfter == balanceBefore);
        }
    }
}

