contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address depositor, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Deposit into the test contract's own balance slot in c.
        c.fallback{value: amount}();

        // Make a successful withdrawal by the test contract.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule over ALL inputs: when withdraw succeeds, the caller's balance is zero
        // and the Ether held by c is exactly the sum of balances owed to all OTHER depositors, i.e. the
        // caller's recorded balance was fully paid out and not left behind.
        assert(reverted || (c.balances(address(this)) == 0 && address(c).balance == c.balances(depositor)));
    }

    receive() external payable {}
}

