contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    bool private withdrawSucceeded;

    function run(uint amount, bool rejectEther) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();
        uint256 b = c.balances(address(this));
        require(b == amount);

        if (rejectEther) {
            // Make every Ether transfer to this test contract fail so that withdraw()
            // is forced to revert, while the balance entry stays b.
            this.setRejectEther(true);
        } else {
            this.setRejectEther(false);
        }

        withdrawSucceeded = true;
        try c.withdraw() {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        uint256 afterBal = c.balances(address(this));
        if (rejectEther) {
            assert(!withdrawSucceeded && afterBal == b);
        } else {
            assert(withdrawSucceeded && afterBal == 0);
        }
    }

    bool private rejectEther;

    function setRejectEther(bool v) external {
        rejectEther = v;
    }

    receive() external payable {
        require(!rejectEther);
    }
}

