contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);
        // Seed the caller's balance in c by sending Ether directly to c's fallback.
        (bool deposited, ) = address(c).call{value: depositAmount}("");
        require(deposited);

        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        // A withdraw with a positive recorded balance must succeed and move exactly
        // the recorded balance from c to the caller, zeroing the caller's entry.
        bool succeeded = !reverted;
        assert(!(depositAmount > 0 && succeeded) ||
               (reverted == false &&
                balAfter == 0 &&
                cBalBefore >= balBefore &&
                cBalAfter == cBalBefore - balBefore));
    }

    receive() external payable {}
}

