        (bool deposited, ) = address(c).call{value: depositAmount}("");
        require(deposited);

        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        // The rule: a successful withdraw zeroes the caller's recorded balance and
        // removes exactly that recorded amount from c's Ether balance.
        assert(reverted || (balAfter == 0 &&
                            cBalBefore >= balBefore &&
                            cBalAfter == cBalBefore - balBefore));
    }

    receive() external payable {}
}

