    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 extraDeposit) public payable {
        require(address(this).balance >= depositAmount + extraDeposit);

        c.fallback{value: depositAmount}();
        uint256 balBefore = c.balances(address(this));
        uint256 cEtherBefore = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cEtherAfter = address(c).balance;

        if (!reverted) {
            assert(address(this).balance == depositAmount + extraDeposit - balBefore);
            assert(cEtherAfter == cEtherBefore - balBefore);
        } else {
            assert(balBefore > cEtherBefore);
            assert(cEtherAfter == cEtherBefore);
        }
    }

    receive() external payable {}
}

