contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 creditAmount, address other) public payable {
        require(other != address(this));
        require(other != address(c));

        // Credit the test contract if desired by sending Ether to c's fallback.
        // The fallback credits balances[msg.sender], i.e. address(this).
        if (creditAmount > 0) {
            require(address(this).balance >= creditAmount);
            (bool sent, ) = address(c).call{value: creditAmount}("");
            require(sent);
        }

        uint256 beforeMine = c.balances(address(this));
        uint256 beforeOther = c.balances(other);

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterMine = c.balances(address(this));
        uint256 afterOther = c.balances(other);

        // other is not the caller, so its balance entry must be unchanged
        assert(afterOther == beforeOther);

        // also sanity-check that the caller's own entry is handled as expected
        if (reverted) {
            assert(afterMine == beforeMine);
        } else {
            assert(afterMine == 0);
        }
    }

    receive() external payable {}
}

